void OpenMediaDevice(int32_t page_request_id, const std::string& device_id, blink::MediaStreamType type, OpenDeviceCallback callback, const MediaDeviceSaltAndOrigin& salt_and_origin) {
  if (!IsOriginAllowedForMediaDevice(salt_and_origin.origin, device_id)) {
    std::move(callback).Run(nullptr, "Origin not allowed to access media device", blink::mojom::MediaStreamRequestResult::kDeniedByUser);
    return;
  }

  MediaStreamManager::GetInstance()->OpenDevice(
      page_request_id, device_id, type, salt_and_origin.salt, std::move(callback),
      base::BindOnce(&OnDeviceStopped));
}

void OpenMediaDevice(int32_t page_request_id, const std::string& device_id, blink::MediaStreamType type,
                     OpenDeviceCallback callback, const MediaDeviceSaltAndOrigin& salt_and_origin) {
  // Check if the origin is allowed to access the media device
  if (!CheckOriginPermission(salt_and_origin.origin)) {
    std::move(callback).Run(false, nullptr);
    return;
  }

  // Call OpenDevice on the media stream manager
  media_stream_manager->OpenDevice(device_id, type, page_request_id, salt_and_origin.salt,
                                   std::move(callback), salt_and_origin.origin);
}

void OpenMediaDevice(int32_t page_request_id, const char* device_id, blink_MediaStreamType type, OpenDeviceCallback callback, MediaDeviceSaltAndOrigin salt_and_origin) {
    if (!IsOriginAllowed(salt_and_origin.origin)) {
        callback(BLINK_MEDIA_DEVICE_ACCESS_DENIED, NULL);
        return;
    }

    MediaStreamManager_OpenDevice(page_request_id, device_id, type, salt_and_origin, callback, OnDeviceStopped);
}
